code.css:
.dl { margin: 0; display: flex; flex-direction: column; }
.dl__row { display: grid; grid-template-columns: 160px 1fr; gap: 16px; padding: 12px 0; border-bottom: 1px solid var(--color-border-default, #d4d4d4); }
.dl__row:last-child { border-bottom: 0; }
.dl__term { margin: 0; font-size: 12px; line-height: 16px; font-weight: 600; color: var(--color-text-secondary, #404040); }
.dl__desc { margin: 0; font-size: 14px; line-height: 20px; color: var(--color-text-primary, #0a0a0a); }
.dl a { color: #1d4ed8; }
.dl a:focus-visible { outline: 2px solid #1d4ed8; outline-offset: 2px; border-radius: 2px; }
@media (max-width: 480px) { .dl__row { grid-template-columns: 1fr; gap: 4px; } }
